const restaurants = [
  ["demo-gr-01", "Demo Greek Bistro", "Heidelberg", ["Greek", "Mediterranean"], 25, "unknown"],
  ["demo-gr-02", "Demo Aegean Table", "Heidelberg", ["Greek"], 38, "online"],
  ["demo-med-01", "Demo Mediterranean Kitchen", "Heidelberg", ["Mediterranean"], 22, "offline"],
  ["demo-it-01", "Demo Pasta Corner", "Heidelberg", ["Italian"], 20, "online"],
  ["demo-ko-01", "Demo Seoul Kitchen", "Heidelberg", ["Korean"], 28, "unknown"],
  ["demo-tr-01", "Demo Anatolia Table", "Heidelberg", ["Turkish", "Mediterranean"], 18, "unknown"],
  ["demo-gr-03", "Demo Aachen Taverna", "Aachen", ["Greek", "Mediterranean"], 24, "offline"]
].map(([id, name, city, cuisine, price, booking]) => ({
  restaurant_id: id,
  name,
  city,
  cuisine,
  price_level_eur: price,
  booking_channel: booking,
  booking_url: null,
  atmosphere: null,
  source: "fictional_demo_fixture",
  last_verified: null
}));

// Parse structured search parameters
let input;
try {
  input = typeof query === "string" ? JSON.parse(query) : query;
} catch {
  return JSON.stringify({
    status: "invalid_input",
    message: "Provide a JSON string with city, cuisine and optional budget_max_eur."
  });
}

if (!input || typeof input !== "object" || Array.isArray(input)) {
  return JSON.stringify({ status: "invalid_input" });
}

const city = String(input.city ?? "").trim();
const cuisine = String(input.cuisine ?? "").trim();
const rawBudget = input.budget_max_eur;
const budget = rawBudget == null ? null : Number(rawBudget);

if (!city) {
  return JSON.stringify({
    status: "missing_city",
    message: "Ask the user which city they want to search in."
  });
}

if (budget !== null && (!Number.isFinite(budget) || budget < 0)) {
  return JSON.stringify({ status: "invalid_budget" });
}

// Filter matching restaurants
const matches = restaurants.filter(r =>
  r.city.toLowerCase() === city.toLowerCase() &&
  (!cuisine || r.cuisine.some(c =>
    c.toLowerCase() === cuisine.toLowerCase()
  )) &&
  (budget === null || r.price_level_eur <= budget)
);

// Sort by price
matches.sort((a, b) => a.price_level_eur - b.price_level_eur);

// Return grounded results
return JSON.stringify({
  status: "ok",
  data_mode: "synthetic_demo",
  search: { city, cuisine, budget_max_eur: budget },
  match_count: matches.length,
  matched_restaurants: matches,
  availability_checked: false,
  message: matches.length
    ? "Matching fictional restaurants found."
    : "No matching restaurants. The agent may search for alternatives."
});
